rest.assertionCode:
def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    data = responseBody.get("data")
    if not isinstance(data, list) or len(data) == 0:
        raise Blocked("no community available")
    def is_uuid(value):
        return (isinstance(value, str) and len(value) == 36
                and all(ch in "0123456789abcdefABCDEF-" for ch in value)
                and value[8] == "-" and value[13] == "-" and value[18] == "-" and value[23] == "-")
    return (statusCode == 200 and responseBody.get("code") == 0
            and all(is_uuid(item.get("id")) and isinstance(item.get("name"), str) and bool(item.get("name")) for item in data)
            and bool(responseBody.get("requestId")))
